-- MEM-39: the pronunciation of vocabulary items, generated by Kokoro. A new
-- table, unknown to the previous version of the API: nothing to adapt.
CREATE TABLE "pronunciations" (
    "itemId" TEXT NOT NULL,
    "text" TEXT NOT NULL,
    "voice" TEXT NOT NULL,
    "audio" BYTEA NOT NULL,
    "mimeType" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "pronunciations_pkey" PRIMARY KEY ("itemId")
);

ALTER TABLE "pronunciations" ADD CONSTRAINT "pronunciations_itemId_fkey" FOREIGN KEY ("itemId") REFERENCES "items"("id") ON DELETE CASCADE ON UPDATE CASCADE;
